import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { open } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { test } from "node:test";

// L30 follow-up (security report limit): synthetic videos carry the IPTC "generated by AI" marker; the Studio offers a
// visible « Généré par IA » mention. Contract: an MP4 gets exactly one XMP uuid box appended, stays playable (ffprobe),
// WebM / broken files come back byte-identical, a second pass adds nothing, a Studio export marked by the owner gets the
// "composite" type, and the Studio keeps the option only as "fr" | "en".
process.env.DATA_DIR = mkdtempSync(path.join(tmpdir(), "sklubot-aivideo-"));
process.env.SESSION_SECRET = "test-secret-test-secret-test-secret";
process.env.NO_SCHEDULER = "1";

const { labelAiVideo, hasAiVideoLabel, videoXmp, topBoxes, labelAiVideoFile, COMPOSITE_SOURCE_TYPE } = await import("../src/aivideo.js");
const { AI_SOURCE_TYPE } = await import("../src/aimedia.js");

const dir = mkdtempSync(path.join(tmpdir(), "aivideo-clip-"));
let clip: Buffer | null = null;
try {
  const out = path.join(dir, "c.mp4");
  execFileSync("ffmpeg", ["-v", "error", "-f", "lavfi", "-i", "testsrc2=size=160x90:rate=12:duration=1", "-pix_fmt", "yuv420p", "-movflags", "+faststart", "-y", out]);
  clip = readFileSync(out);
} catch { clip = null; }

/** A tiny hand-made MP4 (ftyp + free) when ffmpeg is absent: enough for the box logic. */
function box(type: string, body: Buffer) { const h = Buffer.alloc(8); h.writeUInt32BE(8 + body.length); h.write(type, 4, "latin1"); return Buffer.concat([h, body]); }
const tiny = Buffer.concat([box("ftyp", Buffer.from("isom\0\0\x02\0isommp41", "latin1")), box("free", Buffer.alloc(16))]);

test("an MP4 gets one XMP box with the IPTC trainedAlgorithmicMedia type, appended at the end", () => {
  const src = clip ?? tiny;
  assert.equal(hasAiVideoLabel(src), false);
  const out = labelAiVideo(src, "video/mp4");
  assert.ok(out.length > src.length);
  assert.ok(out.subarray(0, src.length).equals(src), "nothing before the new box moves");
  const boxes = topBoxes(out);
  assert.equal(boxes.at(-1)!.type, "uuid");
  assert.equal(boxes.reduce((n, b) => n + b.size, 0), out.length);
  assert.ok(videoXmp(out)!.includes(`DigitalSourceType="${AI_SOURCE_TYPE}"`));
  assert.equal(hasAiVideoLabel(out), true);
  assert.ok(labelAiVideo(out, "video/mp4").equals(out), "a second pass adds nothing");
});

test("the labelled MP4 still plays (ffprobe reads its video stream and duration)", { skip: !clip && "ffmpeg not installed" }, () => {
  const file = path.join(dir, "l.mp4");
  writeFileSync(file, labelAiVideo(clip!, "video/mp4"));
  const probe = execFileSync("ffprobe", ["-v", "error", "-select_streams", "v:0", "-show_entries", "stream=codec_type:format=duration", "-of", "json", file]).toString();
  const j = JSON.parse(probe);
  assert.equal(j.streams[0].codec_type, "video");
  assert.ok(Number(j.format.duration) > 0.5);
});

test("WebM, wrong mime and files whose boxes do not add up are returned unchanged", () => {
  const webm = Buffer.from([0x1a, 0x45, 0xdf, 0xa3, 1, 2, 3, 4, 5, 6, 7, 8]);
  assert.ok(labelAiVideo(webm, "video/webm").equals(webm));
  assert.ok(labelAiVideo(tiny, "image/png").equals(tiny));
  const cut = tiny.subarray(0, tiny.length - 3);
  assert.ok(labelAiVideo(cut, "video/mp4").equals(cut));
});

test("a Studio export on disk gets the composite type, without reading the file whole", async () => {
  const file = path.join(dir, "export.mp4");
  writeFileSync(file, clip ?? tiny);
  const fh = await open(file, "r+");
  const size = (await fh.stat()).size;
  const after = await labelAiVideoFile(fh, size, COMPOSITE_SOURCE_TYPE);
  assert.ok(after > size);
  assert.equal(await labelAiVideoFile(fh, after, COMPOSITE_SOURCE_TYPE), after, "already labelled: unchanged");
  await fh.close();
  const bytes = readFileSync(file);
  assert.equal(bytes.length, after);
  assert.ok(videoXmp(bytes)!.includes("compositeWithTrainedAlgorithmicMedia"));
});

test("the Studio keeps « Généré par IA » only as fr / en", async () => {
  const { storyFor } = await import("../src/videostudio.js");
  const base = { title: "T", aspect: "wide", scenes: [{ text: "a", seconds: 2, style: "type", media: "" }], audio: "", offset: 0, muted: false };
  assert.equal(storyFor("b1", base)!.aiLabel, undefined);
  assert.equal(storyFor("b1", { ...base, aiLabel: true })!.aiLabel, "fr");
  assert.equal(storyFor("b1", { ...base, aiLabel: "en" })!.aiLabel, "en");
  assert.equal(storyFor("b1", { ...base, aiLabel: "<script>" })!.aiLabel, undefined);
});

